base='https://github.com/buffedlizard55-lab/GEMSDOE67/blob/main/'
def page(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · GEMSDOE67</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">GEMS<span> / </span>67</a><nav aria-label="Main"><a href="index.html">Overview</a><a href="executive-summary.html">Submission guide</a><a href="research.html">Research & sources</a><a href="run-card.json">Run card ↗</a></nav></header><main>{body}</main><footer>Orientation & tip-decoding lane · Evidence snapshot: 12 October 2026 · No live leaderboard connection.<br>Maximize P(Win) through evidence. Own the outcome, including negative results.</footer></body></html>'''
score_rows=''
for name,s in scores.items():
 score_rows+=f'<tr><td>{html.escape(name.replace("_"," "))}</td><td>{s["dti"]:.6f}</td><td>{s["ci95"][0]:.6f} – {s["ci95"][1]:.6f}</td><td>{s["withheld_positive_pixels"]:,}</td></tr>'
if not score_rows:score_rows='<tr><td colspan="4">No completed HOLDOUT-DTI measurement yet. No score is inferred.</td></tr>'
version=html.escape(experiment.get('holdout',{}).get('evaluator_version','not yet run'))
